scripts.chinese_remainder_theorem:
def solve(inputs: dict) -> float:
    remainders = inputs['REMAINDERS']
    moduli = inputs['MODULI']

    # Extended GCD to find modular inverse
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            raise ValueError("Modular inverse does not exist")
        return (x % m + m) % m

    # Chinese Remainder Theorem
    def crt(remainders, moduli):
        # Calculate total product of all moduli
        M = 1
        for mod in moduli:
            M *= mod

        x = 0
        for i in range(len(remainders)):
            Mi = M // moduli[i]
            yi = mod_inverse(Mi, moduli[i])
            x += remainders[i] * Mi * yi

        return x % M

    result = crt(remainders, moduli)
    return float(result)
